<?php
require __DIR__.'/../config/auth.php';requireAdmin();require __DIR__.'/../config/db.php';require __DIR__.'/../config/layout.php';
$sectorRows=$pdo->query("SELECT s.nombre,COUNT(d.id) documentos,SUM(CASE WHEN d.estado='aprobado' THEN 1 ELSE 0 END) aprobados,SUM(CASE WHEN d.estado='revision' THEN 1 ELSE 0 END) revision,SUM(CASE WHEN d.estado='obsoleto' THEN 1 ELSE 0 END) obsoletos FROM sectores s LEFT JOIN documentos d ON d.sector_id=s.id AND d.activo=1 GROUP BY s.id ORDER BY s.orden")->fetchAll();
$exp=$pdo->query("SELECT d.titulo,d.fecha_vencimiento,s.nombre sector FROM documentos d JOIN sectores s ON s.id=d.sector_id WHERE d.activo=1 AND d.fecha_vencimiento IS NOT NULL AND d.fecha_vencimiento<=DATE_ADD(CURDATE(),INTERVAL 60 DAY) ORDER BY d.fecha_vencimiento LIMIT 50")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes | NASER</title><link rel="stylesheet" href="<?=app_url('/style.css')?>"></head><body><div class="app"><?php sidebar($pdo,'reportes');?><main class="content"><header class="section-top"><div><p class="eyebrow">ADMINISTRACIÓN</p><h1>Reportes del sistema</h1><p>Resumen documental para una prueba funcional y futura auditoría.</p></div><button class="btn secondary" onclick="window.print()">Imprimir reporte</button></header><section class="table-panel"><div class="section-head"><div><h2>Documentación por sector</h2></div></div><div class="table-wrap"><table><thead><tr><th>Sector</th><th>Total</th><th>Aprobados</th><th>En revisión</th><th>Obsoletos</th></tr></thead><tbody><?php foreach($sectorRows as $r):?><tr><td><strong><?=h($r['nombre'])?></strong></td><td><?=(int)$r['documentos']?></td><td><?=(int)$r['aprobados']?></td><td><?=(int)$r['revision']?></td><td><?=(int)$r['obsoletos']?></td></tr><?php endforeach;?></tbody></table></div></section><section class="table-panel"><div class="section-head"><div><h2>Próximos vencimientos</h2><p>Documentos vencidos o que vencen dentro de 60 días.</p></div></div><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Sector</th><th>Vencimiento</th></tr></thead><tbody><?php foreach($exp as $r):?><tr><td><?=h($r['titulo'])?></td><td><?=h($r['sector'])?></td><td><?=h($r['fecha_vencimiento'])?></td></tr><?php endforeach;?><?php if(!$exp):?><tr><td colspan="3">No hay vencimientos próximos cargados.</td></tr><?php endif;?></tbody></table></div></section></main></div></body></html>
